(* [comment removed for export] *)
Lemma pb_call (a v9 v18 ra pv h v19 : Z) (fxq : FPState) Rq Mq mdq crq kq :
  inv Mq mdq crq kq a -> PESK.sp_hb P h -> xhi + a <= h -> L5.ra_ok ra -> sp - 48 <= pv -> pv + 1 <= sp - 40 ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 48) ->
  getr Rq (PMK.reg 8) = Z_to_bv 64 (fb + 432) -> getr Rq (PMK.reg 9) = Z_to_bv 64 v9 -> getr Rq (PMK.reg 18) = Z_to_bv 64 v18 ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 (fb + 488) -> getr Rq (PMK.reg 11) = Z_to_bv 64 pv -> getr Rq (PMK.reg 19) = Z_to_bv 64 v19 -> csl Rq ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, inv M2 md2 cr2 k2 (a + 1) ->
      getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 48) -> getr R2 (PMK.reg 8) = Z_to_bv 64 (fb + 432) -> getr R2 (PMK.reg 9) = Z_to_bv 64 v9 ->
      getr R2 (PMK.reg 18) = Z_to_bv 64 v18 -> getr R2 (PMK.reg 19) = Z_to_bv 64 v19 -> csl R2 ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 md2) K) ->
