Lemma ev_tail (xs : list eitem) (fxq : FPState) Rq Mq mdq crq kq : xs = xestk -> utf8_valid l = true ->
  inv Mq mdq crq kq (1 + (pl_size n + n)) ->
  getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 48) -> getr Rq (PMK.reg 8) = Z_to_bv 64 (fb + 432) -> csl Rq ->
